replacements.old:
// pass/fail chip for an advisory Λ vs the 0.90 floor (advisory ONLY — never an oracle)
function lamChip(elId, v){
  const el = $(elId); if(!el) return;
  if(num(v) === null){ el.innerHTML = downChip("N/A"); return; }
  const pass = v >= 0.90;
  el.innerHTML = '<span class="pass-chip" style="margin-left:8px;'
    + (pass ? 'color:var(--ok);background:rgba(58,244,200,0.08);border:1px solid rgba(58,244,200,0.3)'
            : 'color:var(--warn);background:rgba(215,185,107,0.08);border:1px solid rgba(215,185,107,0.3)')
    + '">'+(pass?'≥ floor':'below floor')+'</span>';
}

replacements.new:
// Advisory Λ is Conjecture 1: report its relation to the floor, never render pass/fail or green.
function lamChip(elId, v){
  const el = $(elId); if(!el) return;
  if(num(v) === null){ el.innerHTML = downChip("N/A"); return; }
  const relation = v >= 0.90 ? "≥ advisory floor" : "below advisory floor";
  el.innerHTML = grayChip(relation + " · CONJECTURE");
}
